"""离线快照页面的桌面文件浏览器渲染模板。"""

from __future__ import annotations

import html
from typing import Any


def page_header(title: str, description: str) -> str:
    """返回单文件离线页面的顶部框架和内置样式。"""

    safe_title = html.escape(title)
    safe_description = html.escape(description)
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{safe_title}</title>
<style>
:root{{color-scheme:light;font-family:Segoe UI,Microsoft YaHei,Arial,sans-serif;color:#17253a;background:#85b262}}
*{{box-sizing:border-box}}body{{margin:0;min-width:760px;background:linear-gradient(135deg,#d3e7aa 0,#75aa58 52%,#327a3b 100%);min-height:100vh;padding:0 18px}}button,input,select{{font:inherit}}button{{cursor:pointer}}.app{{width:min(1440px,100%);min-height:100vh;margin:auto;background:#fff;box-shadow:0 0 18px #224e2c80;display:grid;grid-template-rows:auto minmax(0,1fr) auto}}.topbar{{min-height:88px;padding:12px 16px;display:flex;align-items:center;gap:14px;background:linear-gradient(#f9fbfc,#dce5e9);border-bottom:1px solid #aeb8bd}}.snapshot-icon{{font-size:34px;line-height:1}}.title-area{{min-width:0;flex:1}}.title-area h1{{font-size:25px;line-height:1.1;margin:0;color:#1a2d46;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}#summary{{font-size:13px;font-style:italic;margin:3px 0 0;color:#293d51}}.description{{margin:1px 0 0;font-size:12px;color:#566575;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}.top-actions{{display:flex;align-items:center;gap:7px}}.search-box{{width:220px;height:28px;border:1px solid #81909a;border-radius:2px;padding:3px 8px;background:white}}.tool-button{{height:28px;border:1px solid #9daab2;border-radius:2px;background:linear-gradient(#fff,#e9edef);color:#213247;padding:2px 9px}}.tool-button:hover{{background:#f7e6a4}}.settings-panel{{position:absolute;right:15px;top:78px;z-index:5;width:305px;padding:10px;background:#fff;border:1px solid #96a3aa;box-shadow:0 4px 15px #0003;font-size:12px}}.settings-panel[hidden]{{display:none}}.settings-panel label{{display:block;margin:7px 0}}.settings-panel select{{margin-left:6px}}.settings-note{{display:block;color:#5c6872;line-height:1.4}}.explorer{{min-height:0;display:grid;grid-template-columns:280px minmax(0,1fr)}}.tree-pane{{min-height:0;overflow:auto;border-right:1px solid #bdc5c7;background:#fbfcfc;padding:5px 0 12px}}.tree-title{{font-size:12px;font-weight:600;color:#52606a;padding:2px 12px 5px}}.tree-folder{{margin:0}}.tree-folder>summary{{height:24px;display:flex;align-items:center;list-style:none;white-space:nowrap}}.tree-folder>summary::-webkit-details-marker{{display:none}}.tree-folder>summary::before{{content:'▸';width:16px;text-align:center;font-size:12px;color:#40505d}}.tree-folder[open]>summary::before{{content:'▾'}}.tree-folder.root>summary::before{{content:''}}.tree-children{{margin-left:15px;border-left:1px dotted #bac3c7}}.tree-select{{height:22px;min-width:0;flex:1;border:0;background:transparent;text-align:left;padding:2px 6px;border-radius:2px;color:#162a41;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.tree-select:hover{{background:#eef5f7}}.tree-select.active{{background:#d9edfa;color:#0b4c7d;font-weight:600}}.folder-icon{{color:#d28a1a;margin-right:4px}}.diff-dot{{display:inline-block;width:7px;height:7px;border-radius:50%;background:#cf3434;margin:0 7px 0 4px;box-shadow:0 0 0 1px #a51818}}.content-pane{{min-width:0;min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto}}.pathbar{{min-height:31px;display:flex;align-items:center;gap:2px;padding:4px 10px;border-bottom:1px solid #c8d0d2;background:#fff}}.breadcrumb{{border:0;background:transparent;color:#154d75;padding:1px 3px;font-size:13px}}.breadcrumb:hover{{text-decoration:underline}}.breadcrumb:disabled{{color:#1e2b35;text-decoration:none;cursor:default}}.crumb-sep{{color:#879198;font-size:12px}}.table-wrap{{min-height:0;overflow:auto}}table{{width:100%;border-collapse:collapse;table-layout:fixed;font-size:13px}}thead{{position:sticky;top:0;z-index:2}}th{{height:25px;padding:0;border-right:1px solid #d7c788;border-bottom:1px solid #c6b366;background:#fff1c9;color:#313842;text-align:left;font-weight:600}}.sort-button{{display:flex;width:100%;height:24px;align-items:center;justify-content:space-between;border:0;background:transparent;color:inherit;padding:1px 7px;text-align:left;font-weight:600}}.sort-button:hover{{background:#ffe49a}}.sort-indicator{{font-size:10px;color:#5d5224}}td{{height:24px;padding:2px 7px;border-right:1px solid #e0e2e3;border-bottom:1px solid #e1e3e4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}tbody tr:hover{{background:#f4f9fc}}tbody tr.selected{{background:#d9edfa}}.name-cell{{width:42%}}.size-cell{{width:95px;text-align:right}}.time-cell{{width:152px}}.created-cell{{width:152px}}.sha-cell{{width:280px;font-family:Consolas,monospace;font-size:11px}}.folder-cell{{width:210px}}.status-cell{{width:100px}}.entry-button{{border:0;background:transparent;padding:0;color:#123d64;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left}}.entry-button:hover{{text-decoration:underline}}.entry-icon{{color:#d28a1a;margin-right:5px}}.file-icon{{color:#61737e;margin-right:5px}}mark{{padding:0;background:#ffe663;color:inherit}}.statusbar{{min-height:33px;padding:7px 11px;border-top:1px solid #c6cdd0;background:#fbfbfb;display:flex;justify-content:space-between;gap:12px;color:#263d4d;font-size:13px}}.statusbar span{{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.export-button{{border:0;background:transparent;color:#21496e;padding:0}}.export-button:hover{{text-decoration:underline}}.more-row{{padding:6px 10px;border-top:1px solid #e0e2e3}}.more-row[hidden]{{display:none}}.more-button{{border:1px solid #abb6bc;background:#f6f8f9;border-radius:2px;padding:3px 10px}}.inspector{{border-top:1px solid #c6cdd0;background:#f8fafb;padding:5px 10px;font-size:12px}}.inspector[hidden]{{display:none}}.metadata{{margin:0;display:grid;grid-template-columns:max-content minmax(0,1fr);gap:2px 10px}}.metadata dt{{font-weight:600;color:#485866}}.metadata dd{{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.metadata dd.hash{{font-family:Consolas,monospace;font-size:11px}}.empty{{color:#61717c;padding:13px}}@media(max-width:900px){{body{{padding:0;min-width:620px}}.explorer{{grid-template-columns:220px minmax(0,1fr)}}.search-box{{width:150px}}.topbar{{padding-inline:10px}}.title-area h1{{font-size:20px}}}}
</style>
</head>
<body>
<div class="app">
<header class="topbar">
<div class="snapshot-icon" aria-hidden="true">▤</div>
<div class="title-area"><h1>{safe_title}</h1><p id="summary"></p><p class="description">{safe_description}</p></div>
<div class="top-actions"><input id="filter" class="search-box" type="search" placeholder="搜索文件、Hash 或状态"><button id="details-toggle" class="tool-button" type="button" aria-pressed="false">详细信息</button><button id="settings-toggle" class="tool-button" type="button" aria-expanded="false">设置</button></div>
</header>
<div id="settings-panel" class="settings-panel" hidden><label>文件所在盘符 <select id="drive-select"></select></label><span id="drive-hint" class="settings-note"></span></div>
"""


def tree_document(payload: dict[str, Any], initial_rows: str) -> str:
    """返回目录树、表格和底部状态栏的静态回退结构。"""

    same_hidden = "" if payload.get("kind") == "compare" else " hidden"
    return f"""<div class="explorer">
<aside class="tree-pane"><div class="tree-title">目录</div><div id="tree"></div></aside>
<main class="content-pane">
<nav id="breadcrumbs" class="pathbar" aria-label="当前目录"></nav>
<div class="table-wrap"><table><thead id="columns"><tr><th class="name-cell">Name</th><th class="size-cell">Size</th><th class="time-cell">Modified</th><th class="created-cell">Created</th><th class="sha-cell">SHA-256</th><th id="same-heading" class="status-cell"{same_hidden}>状态</th></tr></thead><tbody id="rows">{initial_rows}</tbody></table></div>
<div id="more-row" class="more-row"><button id="more" class="more-button" type="button">显示更多</button></div>
<section id="detail" class="inspector" hidden></section>
</main></div>
<footer class="statusbar"><span id="status">正在显示嵌入的静态数据。</span><button id="export-view" class="export-button" type="button">导出当前视图</button></footer>"""


def document_footer() -> str:
    """返回不依赖网络的目录浏览、搜索、排序和导出脚本。"""

    return r"""<script>
(() => {
  const payload = JSON.parse(document.getElementById('diskhtml-archive-data').textContent);
  const tree = document.getElementById('tree'), rows = document.getElementById('rows');
  const columns = document.getElementById('columns'), filter = document.getElementById('filter');
  const summary = document.getElementById('summary'), status = document.getElementById('status');
  const detail = document.getElementById('detail'), breadcrumbs = document.getElementById('breadcrumbs');
  const more = document.getElementById('more'), moreRow = document.getElementById('more-row');
  const detailsToggle = document.getElementById('details-toggle');
  const settingsToggle = document.getElementById('settings-toggle');
  const settingsPanel = document.getElementById('settings-panel');
  const driveSelect = document.getElementById('drive-select'), driveHint = document.getElementById('drive-hint');
  const mode = payload.kind, limit = 500;
  let selectedPath = '', selectedRecord = null, shown = limit, detailed = false;
  let sortKey = 'name', sortDirection = 1;
  const sourcePath = mode === 'scan' ? String((payload.scan || {}).source_path || '') : String((payload.right || {}).source_path || '');
  const driveMatch = /^([a-z]):[\\/]*(.*)$/i.exec(sourcePath);
  const baseName = (path) => String(path || '').split('/').filter(Boolean).at(-1) || '\u5feb\u7167\u6839\u76ee\u5f55';
  const parentOf = (path) => { const parts = String(path || '').split('/').filter(Boolean); parts.pop(); return parts.join('/'); };
  const under = (base, path) => !base || path === base || path.startsWith(base + '/');
  const size = (value) => { if (value === null || value === undefined) return '\u2014'; const units=['B','KB','MB','GB','TB']; let number=Number(value), unit=0; while(number>=1024&&unit<4){number/=1024;unit+=1;} return (unit ? number.toFixed(number>=10?1:2) : Math.round(number))+' '+units[unit]; };
  const time = (value) => { if (!value) return '\u2014'; const date=new Date(value); return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString('zh-CN',{hour12:false}); };
  const records = mode === 'scan' ? (payload.files || []).map(scanRecord) : (payload.entries || []).map(compareRecord);
  const directories = (payload.directories || []).map((row) => ({...row}));
  function scanRecord(row) { return {kind:'file',relative_path:String(row.relative_path||''),name:row.name||baseName(row.relative_path),size_bytes:row.size_bytes,modified_time:row.modified_time,created_time:row.created_time,sha256:row.sha256,status:row.hash_status||'UNKNOWN',error_message:row.error_message||''}; }
  function compareRecord(row) { const current=row.new_size_bytes!==null&&row.new_size_bytes!==undefined; return {kind:'file',relative_path:String(row.relative_path||''),name:baseName(row.relative_path),size_bytes:current?row.new_size_bytes:row.old_size_bytes,modified_time:current?row.new_modified_time:row.old_modified_time,created_time:current?row.new_created_time:row.old_created_time,sha256:current?row.new_sha256:row.old_sha256,status:row.status||'ERROR',error_message:row.error_message||''}; }
  function paths() { const result=new Set(['']); directories.forEach((row)=>result.add(String(row.relative_path||''))); records.forEach((row)=>{let path=parentOf(row.relative_path);while(true){result.add(path);if(!path)break;path=parentOf(path);}}); return [...result]; }
  function folder(path) { const raw=directories.find((row)=>String(row.relative_path||'')===path)||{}; const descendants=records.filter((row)=>under(path,row.relative_path)); const different=mode==='compare'&&descendants.some((row)=>row.status!=='MATCH'); return {kind:'directory',relative_path:path,name:baseName(path),size_bytes:descendants.reduce((total,row)=>total+(Number(row.size_bytes)||0),0),modified_time:raw.modified_time,created_time:raw.created_time,sha256:null,status:different?'DIFFERENT':'MATCH',error_message:''}; }
  function hasDifference(path) { return mode==='compare'&&records.some((row)=>under(path,row.relative_path)&&row.status!=='MATCH'); }
  function localPath(row) { if(!driveMatch) return ''; const root=driveSelect.value+'\\'+driveMatch[2].replace(/[\\/]+$/,''); return root+(row.relative_path?'\\'+row.relative_path.replaceAll('/','\\'):''); }
  function needle() { return filter.value.trim().toLocaleLowerCase(); }
  function isSearch() { return Boolean(needle()); }
  function rowText(row) { return [row.name,row.relative_path,row.sha256||'',row.status||'',row.error_message||''].join(' ').toLocaleLowerCase(); }
  function ordered(items) { const field = sortKey === 'folder' ? (row) => parentOf(row.relative_path) : (row) => row[sortKey]; return [...items].sort((left,right)=>{ if(!isSearch()&&left.kind!==right.kind) return left.kind==='directory'?-1:1; const a=field(left),b=field(right); if(sortKey==='size_bytes'||sortKey==='modified_time'||sortKey==='created_time') return ((Number(a)||0)-(Number(b)||0))*sortDirection; return String(a||'').localeCompare(String(b||''),'zh-CN')*sortDirection; }); }
  function visible() { const search = needle(); if(search){const folders=paths().filter(Boolean).map(folder); return ordered([...folders,...records].filter((row)=>rowText(row).includes(search)));} const folders=paths().filter((path)=>path&&parentOf(path)===selectedPath).map(folder); const files=records.filter((row)=>parentOf(row.relative_path)===selectedPath); return ordered([...folders,...files]); }
  function appendHighlighted(parent, text) { const value=String(text||''); const search=filter.value.trim(); if(!search){parent.textContent=value;return;} const matcher=new RegExp('('+search.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); let position=0; value.replace(matcher,(match,unused,index)=>{if(index>position)parent.append(document.createTextNode(value.slice(position,index)));const mark=document.createElement('mark');mark.textContent=match;parent.append(mark);position=index+match.length;return match;});if(position<value.length)parent.append(document.createTextNode(value.slice(position))); }
  function makeSortButton(label,key,className) { const head=document.createElement('th'); head.className=className; const button=document.createElement('button');button.type='button';button.className='sort-button';const text=document.createElement('span');text.textContent=label;const indicator=document.createElement('span');indicator.className='sort-indicator';indicator.textContent=sortKey===key?(sortDirection>0?'▲':'▼'):'↕';button.append(text,indicator);button.addEventListener('click',()=>{if(sortKey===key)sortDirection*=-1;else{sortKey=key;sortDirection=1;}render();});head.append(button);return head; }
  function renderColumns() { columns.replaceChildren(); const line=document.createElement('tr'); line.append(makeSortButton('Name','name','name-cell'),makeSortButton('Size','size_bytes','size-cell'),makeSortButton('Modified','modified_time','time-cell')); if(detailed)line.append(makeSortButton('Created','created_time','created-cell'),makeSortButton('SHA-256','sha256','sha-cell')); if(isSearch())line.append(makeSortButton('Folder','folder','folder-cell')); if(mode==='compare')line.append(makeSortButton('\u72b6\u6001','status','status-cell')); columns.append(line); }
  function renderBreadcrumbs() { breadcrumbs.replaceChildren(); const items=[['\u5feb\u7167\u6839\u76ee\u5f55','']]; let current='';(selectedPath?selectedPath.split('/'):[]).forEach((part)=>{current=current?current+'/'+part:part;items.push([part,current]);});items.forEach(([label,path],index)=>{if(index){const sep=document.createElement('span');sep.className='crumb-sep';sep.textContent='>';breadcrumbs.append(sep);}const button=document.createElement('button');button.type='button';button.className='breadcrumb';button.textContent=label;button.disabled=path===selectedPath;if(!button.disabled)button.addEventListener('click',()=>select(path));breadcrumbs.append(button);}); }
  function renderTree() { const root={path:'',children:new Map()}; function ensure(path){let node=root,full='';String(path||'').split('/').filter(Boolean).forEach((part)=>{full=full?full+'/'+part:part;if(!node.children.has(part))node.children.set(part,{path:full,children:new Map()});node=node.children.get(part);});return node;}paths().forEach(ensure);function append(parent,node,depth){const item=document.createElement('details');item.className='tree-folder'+(!node.path?' root':'');item.open=depth<2||under(node.path,selectedPath);const summary=document.createElement('summary');const button=document.createElement('button');button.type='button';button.className='tree-select'+(node.path===selectedPath?' active':'');const icon=document.createElement('span');icon.className='folder-icon';icon.textContent='📁';button.append(icon,document.createTextNode(baseName(node.path)));button.addEventListener('click',(event)=>{event.stopPropagation();select(node.path);});summary.append(button);if(node.path&&hasDifference(node.path)){const dot=document.createElement('span');dot.className='diff-dot';dot.title='\u5b58\u5728\u4e0d\u540c\u6587\u4ef6';summary.append(dot);}item.append(summary);const children=document.createElement('div');children.className='tree-children';[...node.children.values()].sort((a,b)=>a.path.localeCompare(b.path,'zh-CN')).forEach((child)=>append(children,child,depth+1));item.append(children);parent.append(item);}tree.replaceChildren();append(tree,root,0); }
  function showDetail(row) { if(!row){detail.hidden=true;return;} const fields=[['Name',row.name],['Type',row.kind==='directory'?'\u6587\u4ef6\u5939':'\u6587\u4ef6'],['Size',size(row.size_bytes)],['Modified',time(row.modified_time)],['Created',time(row.created_time)],['SHA-256',row.sha256||'\u2014']]; if(localPath(row))fields.push(['\u672c\u673a\u8def\u5f84',localPath(row)]); if(mode==='compare')fields.push(['\u72b6\u6001',row.status]); detail.replaceChildren();const data=document.createElement('dl');data.className='metadata';fields.forEach(([key,value])=>{const term=document.createElement('dt'),definition=document.createElement('dd');term.textContent=key;definition.textContent=value||'\u2014';if(key==='SHA-256')definition.className='hash';data.append(term,definition);});detail.append(data);detail.hidden=false; }
  function renderRows(current) { rows.replaceChildren();const view=current.slice(0,shown);if(!view.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.className='empty';cell.colSpan=3+(detailed?2:0)+(isSearch()?1:0)+(mode==='compare'?1:0);cell.textContent='\u5f53\u524d\u8303\u56f4\u6ca1\u6709\u5339\u914d\u6761\u76ee\u3002';row.append(cell);rows.append(row);return;}view.forEach((row)=>{const tableRow=document.createElement('tr');if(selectedRecord&&selectedRecord.relative_path===row.relative_path&&selectedRecord.kind===row.kind)tableRow.className='selected';const name=document.createElement(row.kind==='directory'?'button':'span');name.className=row.kind==='directory'?'entry-button':'entry-label';const icon=document.createElement('span');icon.className=row.kind==='directory'?'entry-icon':'file-icon';icon.textContent=row.kind==='directory'?'📁':'▧';name.append(icon);appendHighlighted(name,row.name);if(row.kind==='directory'){name.type='button';name.addEventListener('click',()=>select(row.relative_path));}else{tableRow.addEventListener('click',()=>{selectedRecord=row;render();});}const cells=[[name,'name-cell'],[size(row.size_bytes),'size-cell'],[time(row.modified_time),'time-cell']];if(detailed)cells.push([time(row.created_time),'created-cell'],[row.sha256||'\u2014','sha-cell']);if(isSearch())cells.push([parentOf(row.relative_path)||'\u5feb\u7167\u6839\u76ee\u5f55','folder-cell']);if(mode==='compare')cells.push([row.status,'status-cell']);cells.forEach(([value,className])=>{const cell=document.createElement('td');cell.className=className;if(value&&typeof value==='object'&&'nodeType'in value)cell.append(value);else cell.textContent=value;tableRow.append(cell);});rows.append(tableRow);}); }
  function updateStatus(current) { const folders=current.filter((row)=>row.kind==='directory'),files=current.filter((row)=>row.kind==='file');const folderBytes=folders.reduce((result,row)=>result+(Number(row.size_bytes)||0),0),fileBytes=files.reduce((result,row)=>result+(Number(row.size_bytes)||0),0);status.textContent=`${folders.length} folders (${size(folderBytes)}), ${files.length} files (${size(fileBytes)})`; if(isSearch())status.textContent='\u641c\u7d22\u7ed3\u679c\uff1a'+status.textContent; }
  function render() { const current=visible();renderColumns();renderRows(current);renderBreadcrumbs();renderTree();showDetail(selectedRecord||folder(selectedPath));updateStatus(current);moreRow.hidden=shown>=current.length; }
  function select(path) { selectedPath=path;selectedRecord=null;shown=limit;filter.value='';render(); }
  function exportView() { const current=visible();const fields=['Name','Size','Modified'];if(detailed)fields.push('Created','SHA-256');if(isSearch())fields.push('Folder');if(mode==='compare')fields.push('\u72b6\u6001');const lines=[fields];current.forEach((row)=>{const values=[row.name,size(row.size_bytes),time(row.modified_time)];if(detailed)values.push(time(row.created_time),row.sha256||'');if(isSearch())values.push(parentOf(row.relative_path));if(mode==='compare')values.push(row.status);lines.push(values);});const csv=lines.map((line)=>line.map((value)=>'"'+String(value??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='diskhtml-current-view.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0); }
  if(mode==='scan'){const stats=payload.statistics||{};summary.textContent=`\u6587\u4ef6 ${stats.total_files||0}，\u76ee\u5f55 ${stats.total_directories||0}，Hash ${stats.hashed_files||0}`;}else{summary.textContent=Object.entries(payload.statistics||{}).map(([key,value])=>key+' '+value).join('；');}
  if(driveMatch){for(let code=65;code<=90;code+=1){const option=document.createElement('option');option.value=String.fromCharCode(code)+':';option.textContent=option.value;driveSelect.append(option);}driveSelect.value=driveMatch[1].toUpperCase()+':';driveHint.textContent='\u5207\u6362\u76d8\u7b26\u540e\uff0cHTML \u4fdd\u7559\u539f\u76ee\u5f55\u7ed3\u6784\uff1bWindows \u8f6f\u8fde\u63a5\u6309\u5f53\u524d\u76ee\u6807\u89e3\u6790\u3002';}else{driveSelect.closest('label').hidden=true;driveHint.textContent='\u5f53\u524d\u5feb\u7167\u672a\u5305\u542b Windows \u76d8\u7b26\u4fe1\u606f\u3002';}
  filter.addEventListener('input',()=>{shown=limit;selectedRecord=null;render();});more.addEventListener('click',()=>{shown+=limit;render();});detailsToggle.addEventListener('click',()=>{detailed=!detailed;detailsToggle.setAttribute('aria-pressed',String(detailed));detailsToggle.textContent=detailed?'精简信息':'详细信息';render();});settingsToggle.addEventListener('click',()=>{settingsPanel.hidden=!settingsPanel.hidden;settingsToggle.setAttribute('aria-expanded',String(!settingsPanel.hidden));});driveSelect.addEventListener('change',()=>showDetail(selectedRecord||folder(selectedPath)));document.getElementById('export-view').addEventListener('click',exportView);render();
})();
</script>
</body>
</html>
"""
